import React, { useEffect, useMemo, useState } from "react";
import ImageCarousel from "../Components/ImageCarousel";
import { HiChevronRight } from "react-icons/hi";

const Gallery = ({ galleryImgData }) => {
  const [imgState, setImgState] = useState("villa");
  const [isRendered, setIsRendered] = useState(false);
  const [carouselItems, setCarouselItems] = useState({});

  const filteredImages = useMemo(
    () => galleryImgData.filter((img) => img.type === imgState),
    [galleryImgData, imgState],
  );

  useEffect(() => {
    const carousel = document.querySelector("#img-container");
    if (isRendered && carousel) {
      carousel.scrollIntoView({ block: "center" });
    }
  }, [isRendered]);

  const categories = [
    { key: "villa", label: "Villas" },
    { key: "room", label: "Rooms" },
    { key: "surroundings", label: "Surroundings" },
  ];

  const featured = filteredImages.slice(0, 4);
  const remaining = filteredImages.slice(4);

  return (
    <section
      id="gallery"
      className="mx-auto max-w-7xl px-4 py-24 sm:px-6 lg:px-8"
    >
      <div className="mb-10 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-sm uppercase tracking-[0.35em] text-amber-300">
            Gallery
          </p>
          <h2 className="text-3xl font-semibold text-white sm:text-4xl">
            A more intimate look at the retreat.
          </h2>
        </div>
        <div
          className="flex flex-wrap gap-3"
          role="tablist"
          aria-label="Gallery categories"
        >
          {categories.map((category) => (
            <button
              key={category.key}
              type="button"
              role="tab"
              aria-selected={imgState === category.key}
              className={`rounded-full px-4 py-2 text-sm font-semibold transition ${
                imgState === category.key
                  ? "bg-amber-400 text-slate-950"
                  : "bg-white/10 text-slate-200 hover:bg-white/20"
              }`}
              onClick={() => setImgState(category.key)}
            >
              {category.label}
            </button>
          ))}
        </div>
      </div>

      <div className="grid gap-5 xl:grid-cols-[1.15fr_0.85fr]">
        <div className="space-y-5">
          {featured.map((item, index) => {
            const isLarge = index === 0;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => {
                  setCarouselItems({ item, index });
                  setIsRendered(true);
                }}
                className={`group relative block w-full overflow-hidden rounded-[2rem] border border-white/10 bg-slate-900/50 text-left shadow-glow ${isLarge ? "min-h-[420px]" : "min-h-[220px]"}`}
              >
                <img
                  src={item.img}
                  alt={`${item.type} view`}
                  className="absolute inset-0 h-full w-full object-cover transition duration-500 group-hover:scale-105"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
                <div className="absolute bottom-0 left-0 right-0 flex items-end justify-between p-6 sm:p-8">
                  <div>
                    <p className="text-xs uppercase tracking-[0.35em] text-amber-300">
                      {imgState}
                    </p>
                    <h3 className="mt-2 text-xl font-semibold text-white">
                      {item.type === "villa"
                        ? "Private villa escape"
                        : item.type === "room"
                          ? "Quiet luxury interiors"
                          : "Wilderness surrounds"}
                    </h3>
                  </div>
                  <span className="rounded-full border border-white/20 bg-white/10 p-2 text-white backdrop-blur">
                    <HiChevronRight size={20} />
                  </span>
                </div>
              </button>
            );
          })}
        </div>

        <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-1">
          {remaining.map((item, index) => (
            <button
              key={item.id}
              type="button"
              onClick={() => {
                setCarouselItems({ item, index: index + 4 });
                setIsRendered(true);
              }}
              className="group relative block min-h-[180px] overflow-hidden rounded-[1.5rem] border border-white/10 bg-slate-900/50 text-left shadow-glow"
            >
              <img
                src={item.img}
                alt={`${item.type} view`}
                className="absolute inset-0 h-full w-full object-cover transition duration-500 group-hover:scale-105"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent" />
              <div className="absolute bottom-0 left-0 p-5">
                <p className="text-xs uppercase tracking-[0.35em] text-amber-300">
                  View
                </p>
                <h3 className="text-lg font-semibold text-white">
                  {item.type}
                </h3>
              </div>
            </button>
          ))}
        </div>
      </div>

      {isRendered && (
        <ImageCarousel
          allImages={filteredImages}
          image={carouselItems}
          setIsRendered={setIsRendered}
        />
      )}
    </section>
  );
};

export default Gallery;
